/**
 * Insurrection Test Kit (GM script macro, Insurrection system only).
 *
 * Creates an "Insurrection Test Kit" folder of items converted from the old
 * Sandbox world (species, roles, backgrounds, boons, weapons, armor, gear, a few
 * abilities, three test mods), plus a ready made Test Operative and a GENESIS
 * Trooper to shoot at. Running it again offers to delete the kit and rebuild.
 * For testing only. Generated by dev/build-test-kit.mjs; do not edit the data.
 */
const KIT = /*__KIT__*/{};
const ROOT_NAME = "Insurrection Test Kit";
const FLAG = { irop: { testKit: true } };

if ( game.system.id !== "irop" ) return ui.notifications.error("The test kit is for the Insurrection system.");
if ( !game.user.isGM ) return ui.notifications.error("The test kit macro is GM only.");

// Rebuild cleanly if the kit is already here.
const existing = game.folders.find(f => (f.type === "Item") && (f.name === ROOT_NAME) && !f.folder);
const oldActors = game.actors.filter(a => a.getFlag("irop", "testKit"));
if ( existing || oldActors.length ) {
  const ok = await foundry.applications.api.DialogV2.confirm({
    window: { title: "Insurrection Test Kit" },
    content: "<p>The test kit is already in this world. Delete its items, folders and test actors, and rebuild?</p>"
  });
  if ( !ok ) return;
  if ( existing ) await existing.delete({ deleteSubfolders: true, deleteContents: true });
  if ( oldActors.length ) await Actor.deleteDocuments(oldActors.map(a => a.id));
}

// Items, one subfolder per kind.
const root = await Folder.create({ name: ROOT_NAME, type: "Item", color: "#42abf2" });
const made = {};
let total = 0;
for ( const [name, list] of Object.entries(KIT) ) {
  const folder = await Folder.create({ name, type: "Item", folder: root.id });
  const docs = await Item.createDocuments(list.map(d => ({ ...d, folder: folder.id, flags: FLAG })));
  for ( const d of docs ) made[d.name] = d;
  total += docs.length;
}

/** A copy of a kit item for an actor, with optional system overrides. */
function take(name, system = {}) {
  const doc = made[name];
  if ( !doc ) { console.warn(`irop test kit: no item named ${name}`); return null; }
  const data = doc.toObject();
  delete data._id;
  delete data.folder;
  data.system = foundry.utils.mergeObject(data.system, system);
  return data;
}

// The Test Operative: a Human Outrider with something of everything.
const operative = await Actor.create({
  name: "Test Operative",
  type: "operative",
  flags: FLAG,
  system: {
    details: {
      callsign: "Kit",
      // Placeholder dossier so the Personnel Record has something to show. Not canon.
      biography: "<p>Test data. The long biography now lives in the Personnel Record, under Bio.</p>",
      record: {
        age: "31", race: "Test data", nationality: "Test data", profession: "Test data", section: "Test data",
        height: "5'10\"", hair: "Black", eyes: "Grey",
        marks: "Test data: burn scar, left forearm",
        enlisted: "Test data", registry: "Test data",
        nextOfKin: { name: "Test Contact", relation: "sibling" },
        timeline: [
          { date: "Test entry", entry: "Replace with this operative's history, one dated line at a time." },
          { date: "Test entry", entry: "Add entries with the Add entry button; the x removes one." }
        ]
      }
    },
    skills: { stealth: { rank: 2 }, awareness: { rank: 2 }, lockpicking: { rank: 1 }, acrobatics: { rank: 1 },
      paraphysics: { rank: 1 }, medical: { rank: 1 } },
    paraphysics: { telekinesis: 1 }
  },
  items: [
    take("Human"), take("Outrider"), take("Slum Dweller"), take("Perception Boon"), take("Agility Boon"),
    take("T1 Pistol", { equipped: true }), take("T1 Assault Rifle"), take("Survival Knife"),
    take("Frag Grenade", { quantity: 2 }), take("Flashbang"),
    take("Kevlar Armor", { equipped: true }), take("Light Weave Armor"),
    take("Medkit", { quantity: 2 }), take("Backpack"),
    take("Gravbolt"), take("Charge"), take("Resilience (1)"),
    take("Reflex Sight (test)"), take("Ceramic Insert (test)")
  ].filter(Boolean)
});

// Fit the sight to the pistol; leave the insert loose to try dragging it onto the armor.
const pistol = operative.items.find(i => i.name === "T1 Pistol");
const sight = operative.items.find(i => i.name === "Reflex Sight (test)");
if ( pistol && sight ) await sight.update({ "system.installedOn": pistol.id });

// The GENESIS Trooper to shoot at.
const trooper = await Actor.create({
  name: "GENESIS Trooper (test)",
  type: "npc",
  flags: FLAG,
  system: { details: { threat: "soldier", faction: "GENESIS Administration" } },
  items: [take("GENESIS"), take("GENESIS AR", { equipped: true }), take("GENESIS Medium Armor", { equipped: true })]
    .filter(Boolean)
});

// Start both at full.
for ( const a of [operative, trooper] ) {
  const v = a.system.vitals;
  await a.update({
    "system.vitals.hp.value": v.hp.max,
    "system.vitals.energy.value": v.energy.max,
    "system.vitals.armor.value": v.armor.max,
    "system.vitals.luck.value": v.luck.max,
    "system.vitals.dodges.value": v.dodges.max
  });
}

ui.notifications.info(`Insurrection test kit: ${total} items, Test Operative and GENESIS Trooper created.`);
operative.sheet.render({ force: true });
